    node.images = Array.isArray(node.images) ? node.images : [];
    node.workflowRef = String(node.workflowRef || node.runSettings?.comfyWorkflow || '').trim();
    node.workflowAppId = String(node.workflowAppId || node.runSettings?.comfyAppId || '').trim();
    node.workflowTitle = String(node.workflowTitle || node.title || node.workflowRef.replace(/\.json$/i, '') || 'ComfyUI 工作流').trim();
    node.title = node.workflowTitle;
    node.workflowFields = Array.isArray(node.workflowFields) ? node.workflowFields : [];
    node.workflowReadiness = node.workflowReadiness && typeof node.workflowReadiness === 'object' ? node.workflowReadiness : {};
    node.workflowStatus = String(node.workflowStatus || (node.workflowReadiness.can_run ? 'ready' : 'needs_preparation')).trim();
    if(node.comfyNodeLayoutVersion !== 2){
        if(!Number.isFinite(Number(node.w)) || Number(node.w) <= 390) node.w = 430;
        if(!Number.isFinite(Number(node.h)) || Number(node.h) <= 260) node.h = comfyWorkflowNodeDefaultHeight(node.workflowFields);
        node.comfyNodeLayoutVersion = 2;
    }
    node.w = Math.max(340, Math.min(1200, Math.round(Number(node.w) || 430)));
    node.h = Math.max(320, Math.min(900, Math.round(Number(node.h) || comfyWorkflowNodeDefaultHeight(node.workflowFields))));
    if(!node.runSettings || typeof node.runSettings !== 'object') node.runSettings = {};
