function ensureSharedEditorInitialSelection(){
    if(!sharedCanvasMode || sharedCanvasReadOnly || sharedEditorInitialSelectionApplied || !nodes.length) return;
    const validSelectedIds = selectedNodeIds().filter(id => nodes.some(node => node?.id === id && node.id !== SMART_LOG_PREVIEW_NODE_ID));
    if(validSelectedIds.length){
        sharedEditorInitialSelectionApplied = true;
        return;
    }
    const interactiveNodes = nodes.filter(node => isSmartImageNode(node) && (node.images || []).some(image => image?.url));
    const viewWidth = shell?.clientWidth || window.innerWidth || 1;
    const viewHeight = shell?.clientHeight || window.innerHeight || 1;
    const scale = safeScale(viewport.scale);
    const visibleInteractive = interactiveNodes.filter(node => {
        const rect = nodeRect(node);
        const left = Number(viewport.x || 0) + rect.x * scale;
        const top = Number(viewport.y || 0) + rect.y * scale;
        const right = left + rect.width * scale;
        const bottom = top + rect.height * scale;
        return right >= 0 && bottom >= 0 && left <= viewWidth && top <= viewHeight;
    });
    const candidates = visibleInteractive.length ? visibleInteractive : interactiveNodes;
    const center = {
        x:(viewWidth / 2 - Number(viewport.x || 0)) / scale,
        y:(viewHeight / 2 - Number(viewport.y || 0)) / scale
    };
    const firstInteractive = candidates.slice().sort((a, b) => {
        const aRect = nodeRect(a);
        const bRect = nodeRect(b);
        const aDistance = Math.hypot((Number(a.x || 0) + aRect.width / 2) - center.x, (Number(a.y || 0) + aRect.height / 2) - center.y);
        const bDistance = Math.hypot((Number(b.x || 0) + bRect.width / 2) - center.x, (Number(b.y || 0) + bRect.height / 2) - center.y);
        return aDistance - bDistance;
    })[0];
    const firstNode = firstInteractive || nodes.find(node => node.id !== SMART_LOG_PREVIEW_NODE_ID) || nodes[0];
    if(!firstNode) return;
    selectedId = firstNode.id;
    selectedIds = [];
    selectedImage = {nodeId:'', index:-1};
    sharedEditorInitialSelectionApplied = true;
}
function applyModifiedNodeSelection(id, event){
    if(!id || !(event?.shiftKey || event?.ctrlKey || event?.metaKey)) return false;
    // 图片单击为了兼容双击预览会延迟提交；Shift 加选必须先提交这次单击，
    // 否则用户快速从图2切到图3时，延迟回调会把多选结果覆盖回图2。
    flushPendingImageClickSelection();
    const current = selectedNodeIds().filter(nodeId => nodes.some(node => node.id === nodeId));
    let next;
    if(event.ctrlKey || event.metaKey){
        // Ctrl/Cmd 是明确的“减选”：点击未选节点不会把它加入当前选择。
        next = current.filter(nodeId => nodeId !== id);
    } else if(event.shiftKey){
        // Shift 是明确的“加选”：再次点已选节点时保持选中，不会误取消。
        next = current.includes(id) ? current : [...current, id];
    }
    selectedId = next.length === 1 ? next[0] : '';
    selectedIds = next.length > 1 ? next : [];
    selectedImage = {nodeId:'', index:-1};
    if(smartCascadeAnyRunning()) smartCascadeSilentSelection = false;
    syncSelectionUi();
    updateComposer();
    return true;
}
