function renderSizeControls(prefix='', includeSource=false){
    const ratioKey = prefix ? `${prefix}Ratio` : 'ratio';
    const resKey = prefix ? `${prefix}Resolution` : 'resolution';
    const ratios = [
        ...smartRatioOptions(prefix, includeSource).map(([value, label]) => [value, label]),
        ['custom', tr('canvas.custom') || '自定义']
    ];
    const resolutionOptions = (!prefix && settings.engine === 'api') ? ['auto','1k','2k','4k','custom'] : ['1k','2k','4k','custom'];
    return `<select data-param="${resKey}">
            ${resolutionOptions.map(v => optionHtml(v, v === 'auto' ? '自动' : (v === 'custom' ? (tr('canvas.custom') || '自定义') : v.toUpperCase()), settings[resKey] || (prefix ? '1k' : defaultSmartApiResolution(settings.model)))).join('')}
        </select>
        <select data-param="${ratioKey}" ${settings[resKey] === 'custom' || settings[resKey] === 'auto' ? 'disabled' : ''}>
            ${ratios.map(([v,l]) => `<option value="${escapeHtml(v)}" ${v === (settings[ratioKey] || 'square') ? 'selected' : ''}>${escapeHtml(l)}</option>`).join('')}
        </select>`;
}
function ratioLabel(prefix=''){
    const ratioKey = prefix ? `${prefix}Ratio` : 'ratio';
    const customKey = prefix ? `${prefix}CustomRatio` : 'customRatio';
    const sourceLabel = sourceImageRatioLabel(prefix) || tr('smart.imageRatio');
    const value = settings[ratioKey] || 'square';
    if(value === 'source') return sourceLabel;
    if(value === 'custom') return settings[customKey] || tr('smart.custom');
    return SMART_RATIO_VALUE_MAP[value] || '1:1';
}
function gcdInt(a, b){
    a = Math.abs(Math.round(Number(a) || 0));
    b = Math.abs(Math.round(Number(b) || 0));
    while(b){ const t = b; b = a % b; a = t; }
    return a || 1;
}
function imageSizeForRatio(img){
    const w = Math.round(Number(img?.natural_w || img?.width || img?.w || 0));
    const h = Math.round(Number(img?.natural_h || img?.height || img?.h || 0));
    return w > 0 && h > 0 ? {w, h} : null;
}
function sourceRatioImageForNode(node){
    // “适配输入”必须与界面中参考图缩略图的顺序一致：始终以图1为准。
    // 不要读取 node.images 或当前选中的画布图，它们可能是图2或一次旧的生成结果。
    const references = visibleReferenceImagesFor(node)
        .filter(img => img?.url && !isAudioMediaItem(img));
    const firstReferenceWithSize = references.find(img => imageSizeForRatio(img));
    if(firstReferenceWithSize) return firstReferenceWithSize;
    if(references.length) return references[0];

    // 无参考图的旧画布继续回退到节点自身图片，避免影响已有单图节点。
    const images = (node?.images || []).filter(img => img?.url && !isAudioMediaItem(img));
    return images.find(img => imageSizeForRatio(img)) || images[0] || null;
}
function sourceDimensionsForImage(img){
    const size = imageSizeForRatio(img);
    if(!size) return null;
    return {w:size.w, h:size.h};
}
function agentChatProviders(){
    return chatApiProviders();
}
function resolveAgentProviderId(providerId=''){
    const providers = agentChatProviders();
    if(providers.some(provider => provider.id === providerId)) return providerId;
    return providers[0]?.id || resolveChatProviderId(providerId);
}
function agentProviderModels(providerId=''){
    const provider = agentChatProviders().find(item => item.id === resolveAgentProviderId(providerId));
    return [...new Set(provider?.chat_models || [])];
}
function resolveAgentModel(model='', providerId=''){
    const models = agentProviderModels(providerId);
    return models.includes(model) ? model : (models[0] || resolveChatModel(model, providerId));
}
function sourceImageRatioLabel(prefix=''){
    const node = activeComposerNode() || selectedNode();
    const ratio = sourceDimensionsForImage(sourceRatioImageForNode(node));
    if(!ratio) return '';
    return `${ratio.w}:${ratio.h}`;
}
function applySourceRatioToSettings(prefix=''){
    const ratioKey = prefix ? `${prefix}Ratio` : 'ratio';
    if(settings[ratioKey] !== 'source') return;
    const ratio = sourceDimensionsForImage(sourceRatioImageForNode(activeComposerNode() || selectedNode()));
    if(!ratio) return;
    const customKey = prefix ? `${prefix}CustomRatio` : 'customRatio';
    const wKey = prefix ? `${prefix}CustomRatioWidth` : 'customRatioWidth';
    const hKey = prefix ? `${prefix}CustomRatioHeight` : 'customRatioHeight';
    settings[wKey] = ratio.w;
    settings[hKey] = ratio.h;
    settings[customKey] = `${ratio.w}:${ratio.h}`;
}
function resolutionLabel(prefix=''){
    const resKey = prefix ? `${prefix}Resolution` : 'resolution';
    const sizeKey = prefix ? `${prefix}CustomSize` : 'customSize';
    const value = settings[resKey] || ((!prefix && settings.engine === 'api') ? defaultSmartApiResolution(settings.model) : '1k');
    if(value === 'auto') return '自动';
    return value === 'custom' ? (settings[sizeKey] || tr('smart.custom')) : value.toUpperCase();
}
function ratioIconClass(value){
    if(value === 'portrait14' || value === 'portrait18') return 'r-portrait-extreme';
    if(value === 'landscape41' || value === 'landscape81') return 'r-landscape-extreme';
    if(value === 'ratio45') return 'r-portrait43';
    if(value === 'ratio54') return 'r-landscape43';
    if(value === 'portrait') return 'r-portrait';
    if(value === 'portrait43') return 'r-portrait43';
    if(value === 'landscape') return 'r-landscape';
    if(value === 'landscape43') return 'r-landscape43';
    if(value === 'wide' || value === 'ultrawide') return 'r-wide';
    if(value === 'story' || value === 'ultratall') return 'r-story';
    if(value === 'source') return 'r-source';
    if(value === 'custom') return 'r-custom';
    return '';
}
function videoAspectIconClass(value){
    if(value === '16:9' || value === '21:9') return 'r-wide';
    if(value === '9:16' || value === '9:21') return 'r-story';
    if(value === '4:3') return 'r-landscape43';
    if(value === '3:4') return 'r-portrait43';
    if(value === 'keep_ratio' || value === 'adaptive') return 'r-source';
    return '';
}
function renderImageModelControl(providers, models){
    const modelName = settings.model || tr('smart.model');
    return `<div class="smart-control image-model-control">
        <button class="smart-pill image-model-trigger" type="button" aria-label="${escapeHtml(`${tr('smart.imageModel')}：${modelName}`)}" aria-haspopup="true" aria-expanded="false" title="${escapeHtml(modelName)}">
            <i data-lucide="sparkles"></i><span class="image-model-trigger-text"><span class="image-model-name">${escapeHtml(modelName)}</span></span><i data-lucide="chevron-down" class="pill-caret"></i>
        </button>
        <div class="smart-popover image-model-popover">
            <div class="image-model-popover-head"><i data-lucide="sparkles"></i><span>${escapeHtml(tr('smart.imageModel'))}</span></div>
            <div class="image-model-picker">
                <div class="image-model-picker-column">
                    <div class="image-model-picker-label">${escapeHtml(tr('smart.apiPlatform'))}</div>
                    <div class="image-model-provider-list">
                        ${providers.map(p => `<button type="button" class="image-model-option ${p.id === settings.provider_id ? 'active' : ''}" data-smart-param="provider_id" data-smart-value="${escapeHtml(p.id)}" title="${escapeHtml(p.name || p.id)}"><span>${escapeHtml(p.name || p.id)}</span></button>`).join('') || `<div class="image-model-empty">${escapeHtml(tr('smart.noApiPlatform'))}</div>`}
                    </div>
                </div>
                <div class="image-model-picker-column">
                    <div class="image-model-picker-label">${escapeHtml(tr('smart.imageModel'))}<small>${models.length}</small></div>
                    <div class="image-model-options">
                        ${models.map(m => `<button type="button" class="image-model-option ${m === settings.model ? 'active' : ''}" data-smart-param="model" data-smart-value="${escapeHtml(m)}" title="${escapeHtml(m)}"><span>${escapeHtml(m)}</span></button>`).join('') || `<div class="image-model-empty">${escapeHtml(tr('smart.noImageModel'))}</div>`}
                    </div>
                </div>
            </div>
        </div>
    </div>`;
}
function readPromptOptimizerPreference(){
    try {
        const value = JSON.parse(localStorage.getItem(PROMPT_OPTIMIZER_MODEL_KEY) || '{}');
        return {provider:String(value?.provider || ''), model:String(value?.model || '')};
    } catch(e) {
        return {provider:'', model:''};
    }
}
function promptOptimizerApiProviders(){
    // 提示词优化只使用用户配置的 API 网站；本地/CLI 模型不混入这里，
    // 避免把“优化模型”误当成所有本机可用聊天模型。
    const excluded = new Set(['codex', 'gpt-cli', 'jimeng-cli', 'jimeng']);
    return chatApiProviders().filter(provider => !excluded.has(String(provider.id || '').toLowerCase()));
}
function resolvePromptOptimizerProviderId(providerId=''){
    const providers = promptOptimizerApiProviders();
    if(providers.some(provider => provider.id === providerId)) return providerId;
    return providers[0]?.id || '';
}
function promptOptimizerProviderModels(providerId=''){
    const provider = promptOptimizerApiProviders().find(item => item.id === providerId);
    return [...new Set(provider?.chat_models || [])];
}
function promptOptimizerSelection(){
    const saved = readPromptOptimizerPreference();
    const provider = resolvePromptOptimizerProviderId(saved.provider);
    const models = promptOptimizerProviderModels(provider);
    return {provider, model:models.includes(saved.model) ? saved.model : (models[0] || '')};
}
function promptOptimizerOptionValue(provider, model){
    return `${encodeURIComponent(provider || '')}|${encodeURIComponent(model || '')}`;
}
function parsePromptOptimizerOptionValue(value=''){
    const [provider='', model=''] = String(value || '').split('|', 2);
    try { return {provider:decodeURIComponent(provider), model:decodeURIComponent(model)}; }
    catch(e) { return {provider, model}; }
}
function refreshPromptOptimizerModelSelect(){
    if(!promptOptimizerModelMenu || !promptOptimizerModelButton || !promptOptimizerModelLabel) return;
    const providers = promptOptimizerApiProviders();
    const selected = promptOptimizerSelection();
    if(!providers.length){
        promptOptimizerModelLabel.textContent = '未配置聊天模型';
        promptOptimizerModelMenu.innerHTML = '<div class="prompt-optimizer-model-empty">请先在 API 设置中拉取聊天模型</div>';
        promptOptimizerModelButton.disabled = true;
        return;
    }
    promptOptimizerModelButton.disabled = false;
    promptOptimizerModelLabel.textContent = selected.model || '请选择';
    promptOptimizerModelMenu.innerHTML = providers.map(provider => {
        const models = promptOptimizerProviderModels(provider.id);
        return `<section class="prompt-optimizer-model-group"><div class="prompt-optimizer-model-group-title">${escapeHtml(provider.name || provider.id)}</div>${models.map(model => {
            const active = provider.id === selected.provider && model === selected.model;
            return `<button type="button" class="prompt-optimizer-model-option ${active ? 'active' : ''}" role="option" aria-selected="${active ? 'true' : 'false'}" data-provider="${escapeAttr(provider.id)}" data-model="${escapeAttr(model)}"><span>${escapeHtml(model)}</span>${active ? '<i data-lucide="check"></i>' : ''}</button>`;
        }).join('')}</section>`;
    }).join('');
    if(selected.provider && selected.model){
        localStorage.setItem(PROMPT_OPTIMIZER_MODEL_KEY, JSON.stringify(selected));
    }
    refreshIcons();
}
function closePromptOptimizerModelMenu(){
    if(!promptOptimizerModelControl || !promptOptimizerModelButton) return;
    promptOptimizerModelControl.classList.remove('open');
    promptOptimizerModelButton.setAttribute('aria-expanded', 'false');
}
function togglePromptOptimizerModelMenu(){
    if(!promptOptimizerModelControl || !promptOptimizerModelButton || promptOptimizerModelButton.disabled) return;
    const open = !promptOptimizerModelControl.classList.contains('open');
    promptOptimizerModelControl.classList.toggle('open', open);
    promptOptimizerModelButton.setAttribute('aria-expanded', open ? 'true' : 'false');
}
function renderRatioControl(prefix='', includeSource=false){
    const ratioKey = prefix ? `${prefix}Ratio` : 'ratio';
    const resKey = prefix ? `${prefix}Resolution` : 'resolution';
    const ratios = [
        ...smartRatioOptions(prefix, includeSource).map(([value, label]) => [value, label]),
        ['custom', tr('smart.custom')]
    ];
    return `<div class="smart-control ratio-control">
        <button class="smart-pill" type="button"><i data-lucide="scan"></i><span>${escapeHtml(ratioLabel(prefix))}</span></button>
        <div class="smart-popover">
            <div class="smart-popover-title">${escapeHtml(tr('smart.ratio'))}</div>
            <div class="ratio-grid">
                ${ratios.map(([value, label]) => `<button type="button" class="ratio-option ${value === (settings[ratioKey] || 'square') ? 'active' : ''}" data-smart-param="${ratioKey}" data-smart-value="${escapeHtml(value)}"><span class="ratio-icon ${ratioIconClass(value)}"></span><span>${escapeHtml(label)}</span></button>`).join('')}
            </div>
        </div>
    </div>`;
}
function renderResolutionControl(prefix=''){
    const resKey = prefix ? `${prefix}Resolution` : 'resolution';
    const options = (!prefix && settings.engine === 'api') ? ['auto','1k','2k','4k','custom'] : ['1k','2k','4k','custom'];
    const current = settings[resKey] || ((!prefix && settings.engine === 'api') ? defaultSmartApiResolution(settings.model) : '1k');
    const allowAuto = !prefix && settings.engine === 'api' && settings.apiKind !== 'video' && isGptImageAutoSizeModel(settings.model);
    return `<div class="smart-control resolution-control">
        <button class="smart-pill" type="button"><i data-lucide="monitor"></i><span>${escapeHtml(resolutionLabel(prefix))}</span></button>
        <div class="smart-popover compact-popover">
            <div class="smart-popover-title">${escapeHtml(tr('smart.resolution'))}</div>
            <div class="seg-row">
                ${options.map(value => `<button type="button" class="${value === current ? 'active' : ''}" data-smart-param="${resKey}" data-smart-value="${value}" ${value === 'auto' && !allowAuto ? 'disabled' : ''}>${value === 'auto' ? '自动' : (value === 'custom' ? escapeHtml(tr('smart.custom')) : value.toUpperCase())}</button>`).join('')}
            </div>
        </div>
    </div>`;
}
function sizePickerScope(prefix=''){
    const resKey = prefix ? `${prefix}Resolution` : 'resolution';
    const ratioKey = prefix ? `${prefix}Ratio` : 'ratio';
    const value = settings[resKey] || ((!prefix && settings.engine === 'api') ? defaultSmartApiResolution(settings.model) : '1k');
    if(value === 'auto') return 'auto';
    if(value === 'custom' || settings[ratioKey] === 'custom') return 'custom';
    return 'preset';
}
function sizePickerDefaultResolution(prefix=''){
    const value = (!prefix && settings.engine === 'api') ? defaultSmartApiResolution(settings.model) : '1k';
    return value === 'auto' ? '1k' : value;
}
function migrateLegacyCustomSizePicker(prefix=''){
    const resKey = prefix ? `${prefix}Resolution` : 'resolution';
    const ratioKey = prefix ? `${prefix}Ratio` : 'ratio';
    if(settings[resKey] !== 'custom' || settings.outpaintResolutionLocked) return;
    const sizeKey = prefix ? `${prefix}CustomSize` : 'customSize';
    const widthKey = prefix ? `${prefix}CustomWidth` : 'customWidth';
    const heightKey = prefix ? `${prefix}CustomHeight` : 'customHeight';
    const ratioValueKey = prefix ? `${prefix}CustomRatio` : 'customRatio';
    const ratioWidthKey = prefix ? `${prefix}CustomRatioWidth` : 'customRatioWidth';
    const ratioHeightKey = prefix ? `${prefix}CustomRatioHeight` : 'customRatioHeight';
    const parsed = parseSizeValue(settings[sizeKey]) || {
        width:Number(settings[widthKey]) || 0,
        height:Number(settings[heightKey]) || 0
    };
    if(parsed.width > 0 && parsed.height > 0){
        settings[ratioWidthKey] = Number(parsed.width);
        settings[ratioHeightKey] = Number(parsed.height);
        settings[ratioValueKey] = `${parsed.width}:${parsed.height}`;
    }
    const longest = Math.max(Number(parsed.width) || 0, Number(parsed.height) || 0);
    settings[resKey] = longest > 2048 ? '4k' : (longest > 1024 ? '2k' : '1k');
    settings[ratioKey] = 'custom';
}
function seedCustomRatioPicker(prefix=''){
    const resKey = prefix ? `${prefix}Resolution` : 'resolution';
    const ratioKey = prefix ? `${prefix}Ratio` : 'ratio';
    const ratioValueKey = prefix ? `${prefix}CustomRatio` : 'customRatio';
    const ratioWidthKey = prefix ? `${prefix}CustomRatioWidth` : 'customRatioWidth';
    const ratioHeightKey = prefix ? `${prefix}CustomRatioHeight` : 'customRatioHeight';
    if(settings[resKey] === 'custom') migrateLegacyCustomSizePicker(prefix);
    if(!settings[ratioWidthKey] || !settings[ratioHeightKey]){
        const resolution = ['1k','2k','4k'].includes(settings[resKey]) ? settings[resKey] : '1k';
        const parsed = parseSizeValue(apiImageSize(settings[ratioKey] || 'square', resolution, settings[ratioValueKey] || '', ''));
        if(parsed){
            const divisor = gcdInt(parsed.width, parsed.height);
            settings[ratioWidthKey] = Math.max(1, Math.round(Number(parsed.width) / divisor));
            settings[ratioHeightKey] = Math.max(1, Math.round(Number(parsed.height) / divisor));
        } else {
            settings[ratioWidthKey] = 1;
            settings[ratioHeightKey] = 1;
        }
    }
    settings[ratioValueKey] = `${settings[ratioWidthKey]}:${settings[ratioHeightKey]}`;
    settings[ratioKey] = 'custom';
    if(!['1k','2k','4k'].includes(settings[resKey])) settings[resKey] = '1k';
}
function sizePickerLabel(prefix=''){
    const scope = sizePickerScope(prefix);
    if(scope === 'auto') return '自动';
    if(scope === 'custom'){
        const resKey = prefix ? `${prefix}Resolution` : 'resolution';
        const ratioKey = prefix ? `${prefix}Ratio` : 'ratio';
        const resText = resolutionLabel(prefix);
        const ratioText = ratioLabel(prefix);
        if(settings[resKey] === 'custom' && settings[ratioKey] === 'custom') return `自定义 · ${resText} · ${ratioText}`;
        if(settings[resKey] === 'custom') return `自定义 · ${resText}`;
        if(settings[ratioKey] === 'custom') return `自定义 · ${ratioText} · ${resText}`;
        return `自定义 · ${resText}`;
    }
    return `${ratioLabel(prefix)} · ${resolutionLabel(prefix)}`;
}
function refreshRenderedSizePickerLabel(prefix=''){
    if(!dynamicParams) return;
    [...dynamicParams.querySelectorAll('.size-picker-control')]
        .filter(control => control.dataset.sizePrefix === prefix)
        .forEach(control => {
            const label = control.querySelector('.generation-settings-value');
            if(label) label.textContent = generationSettingsSummary(prefix);
        });
}
function generationSettingsSummary(prefix=''){
    const parts = [sizePickerLabel(prefix)];
    if(imageModelSupportsQuality(settings)){
        const labels = {auto:tr('smart.qualityAuto'), low:tr('smart.qualityLow'), medium:tr('smart.qualityMid'), high:tr('smart.qualityHigh')};
        if(settings.engine === 'api' && isGptImage25Model(settings.model)){
            labels.xhigh = tr('smart.qualityXhigh');
            labels.max = tr('smart.qualityMax');
        }
        parts.push(labels[settings.quality] || labels.auto);
    }
    return parts.filter(Boolean).join(' · ');
}
function renderGenerationSettingsControl(prefix='', includeSource=false){
    const ratioKey = prefix ? `${prefix}Ratio` : 'ratio';
    const resKey = prefix ? `${prefix}Resolution` : 'resolution';
    const customRatioKey = prefix ? `${prefix}CustomRatio` : 'customRatio';
    migrateLegacyCustomSizePicker(prefix);
    if(settings[ratioKey] === 'source') applySourceRatioToSettings(prefix);
    const options = (!prefix && settings.engine === 'api') ? ['auto','1k','2k','4k'] : ['1k','2k','4k'];
    const currentRes = settings[resKey] || ((!prefix && settings.engine === 'api') ? defaultSmartApiResolution(settings.model) : '1k');
    const currentRatio = settings[ratioKey] || 'square';
    const currentCustomRatio = settings[customRatioKey] || (currentRatio === 'source' ? sourceImageRatioLabel(prefix) : '');
    const allowAuto = !prefix && settings.engine === 'api' && settings.apiKind !== 'video' && isGptImageAutoSizeModel(settings.model);
    const ratios = smartRatioPickerOptions(prefix, includeSource).map(([value, label, sub]) => value === 'source'
        ? [value, '适配输入', '参考图比例']
        : [value, label, sub]);
    if(currentRatio !== 'custom' && currentRatio !== 'source' && !ratios.some(([value]) => value === currentRatio)){
        ratios.push([currentRatio, ratioLabel(prefix), '当前比例']);
    }
    const wKey = prefix ? `${prefix}CustomRatioWidth` : 'customRatioWidth';
    const hKey = prefix ? `${prefix}CustomRatioHeight` : 'customRatioHeight';
    const exactCustomSize = settings.outpaintResolutionLocked && currentRes === 'custom';
    const includeQuality = imageModelSupportsQuality(settings);
    const includeBackground = imageModelSupportsBackground(settings);
    const qualityLabels = {auto:tr('smart.qualityAuto'), low:tr('smart.qualityLow'), medium:tr('smart.qualityMid'), high:tr('smart.qualityHigh')};
    if(settings.engine === 'api' && isGptImage25Model(settings.model)){
        qualityLabels.xhigh = tr('smart.qualityXhigh');
        qualityLabels.max = tr('smart.qualityMax');
    }
    const qualityValue = Object.prototype.hasOwnProperty.call(qualityLabels, settings.quality) ? settings.quality : 'auto';
    if(includeQuality && settings.quality !== qualityValue) settings.quality = qualityValue;
    const backgroundValue = normalizeSmartBackground(settings.background);
    if(includeBackground && settings.background !== backgroundValue) settings.background = backgroundValue;
    const backgroundLabels = {
        opaque:tr('smart.backgroundOpaque'),
        transparent:tr('smart.backgroundTransparent'),
    };
    const resolutionChoices = exactCustomSize ? [] : options.filter(value => value !== 'auto' || allowAuto);
    const customWidthKey = prefix ? `${prefix}CustomWidth` : 'customWidth';
    const customHeightKey = prefix ? `${prefix}CustomHeight` : 'customHeight';
    return `<div class="smart-control size-picker-control generation-settings-control" data-size-prefix="${escapeHtml(prefix)}">
        <button class="smart-pill size-picker-pill generation-settings-trigger" type="button" aria-haspopup="dialog" aria-expanded="false" aria-controls="generationSettingsPopover" aria-label="生成参数">
            <i data-lucide="sliders-horizontal"></i><span class="generation-settings-label">参数</span><span class="generation-settings-value">${escapeHtml(generationSettingsSummary(prefix))}</span><i data-lucide="chevron-down" class="generation-settings-caret"></i>
        </button>
        <div id="generationSettingsPopover" class="smart-popover size-picker-popover" role="dialog" aria-label="生成参数">
            <div class="generation-settings-head">
                <div><strong>生成参数</strong></div>
                <button type="button" class="generation-settings-close" aria-label="关闭参数面板"><i data-lucide="x"></i></button>
            </div>
            <div class="generation-settings-body">
                ${exactCustomSize ? `<section class="generation-settings-section generation-settings-exact-size">
                    <div class="generation-settings-section-head"><strong>扩图尺寸</strong><span>${escapeHtml(settings.customSize || '输入像素尺寸')}</span></div>
                    <div class="size-custom-row"><input type="number" min="1" data-param="${customWidthKey}" value="${escapeHtml(settings[customWidthKey] || '')}" placeholder="宽度"><span>×</span><input type="number" min="1" data-param="${customHeightKey}" value="${escapeHtml(settings[customHeightKey] || '')}" placeholder="高度"></div>
                </section>` : `<section class="generation-settings-section generation-settings-dimension">
                    <div class="generation-settings-section-head"><strong>画质</strong></div>
                    <div class="generation-settings-segments generation-settings-resolution" role="group" aria-label="分辨率">
                        ${resolutionChoices.map(value => {
                            const size = value === 'auto' ? '模型决定' : apiImageSize(currentRatio, value, currentCustomRatio, '') || '';
                            const sizeHint = size ? ` title="${escapeHtml(size)}" aria-label="${escapeHtml(value === 'auto' ? '自动' : value.toUpperCase())}，${escapeHtml(size)}"` : '';
                            return `<button type="button" class="generation-settings-choice ${value === currentRes ? 'active' : ''}" data-smart-param="${resKey}" data-smart-value="${value}" aria-pressed="${value === currentRes ? 'true' : 'false'}"${sizeHint}><strong>${value === 'auto' ? '自动' : value.toUpperCase()}</strong></button>`;
                        }).join('')}
                    </div>
                    ${includeQuality ? `<div class="generation-settings-segments generation-settings-quality" role="group" aria-label="生成质量">
                        ${['auto','max','xhigh','high','medium','low'].filter(value => Object.prototype.hasOwnProperty.call(qualityLabels, value)).map(value => `<button type="button" class="generation-settings-compact-choice ${value === qualityValue ? 'active' : ''}" data-smart-param="quality" data-smart-value="${value}" aria-pressed="${value === qualityValue ? 'true' : 'false'}">${escapeHtml(qualityLabels[value])}</button>`).join('')}
                    </div>` : ''}
                </section>`}
                ${includeBackground ? `<section class="generation-settings-section generation-settings-secondary generation-settings-background-section">
                    <div class="generation-settings-section-head"><strong>背景</strong></div>
                    <div class="generation-settings-segments generation-settings-background" role="group" aria-label="背景">
                        ${Object.entries(backgroundLabels).map(([value, label]) => `<button type="button" class="generation-settings-compact-choice ${value === backgroundValue ? 'active' : ''}" data-smart-param="background" data-smart-value="${value}" aria-pressed="${value === backgroundValue ? 'true' : 'false'}">${escapeHtml(label)}</button>`).join('')}
                    </div>
                </section>` : ''}
                ${!exactCustomSize && currentRes !== 'auto' ? `<section class="generation-settings-section generation-settings-ratios-section">
                    <div class="generation-settings-section-head"><strong>比例</strong></div>
                    <div class="generation-settings-ratio-grid" role="group" aria-label="宽高比">
                        ${ratios.map(([value, label]) => `<button type="button" class="generation-settings-ratio ${value === currentRatio ? 'active' : ''}" data-smart-param="${ratioKey}" data-smart-value="${escapeHtml(value)}" aria-pressed="${value === currentRatio ? 'true' : 'false'}"><span class="generation-settings-icon-slot" aria-hidden="true"><span class="ratio-icon ${ratioIconClass(value)}"></span></span><strong>${escapeHtml(label)}</strong></button>`).join('')}
                        <button type="button" class="generation-settings-ratio generation-settings-custom-ratio ${currentRatio === 'custom' ? 'active' : ''}" data-size-scope="custom" data-size-prefix="${escapeHtml(prefix)}" aria-pressed="${currentRatio === 'custom' ? 'true' : 'false'}"><span class="generation-settings-icon-slot" aria-hidden="true"><span class="generation-settings-custom-icon"><i data-lucide="scan"></i></span></span><strong>自定义</strong></button>
                    </div>
                    ${currentRatio === 'custom' ? `<div class="generation-settings-custom-fields"><div class="size-custom-row"><input type="number" min="1" data-param="${wKey}" value="${escapeHtml(settings[wKey] || '')}" placeholder="比例宽"><span>:</span><input type="number" min="1" data-param="${hKey}" value="${escapeHtml(settings[hKey] || '')}" placeholder="比例高"></div></div>` : ''}
                </section>` : ''}
            </div>
        </div>
    </div>`;
}
function renderInlineCustomRatioFields(prefix=''){
    const ratioKey = prefix ? `${prefix}Ratio` : 'ratio';
    if(settings[ratioKey] === 'source') return '';
    if(settings[ratioKey] !== 'custom') return '';
    const wKey = prefix ? `${prefix}CustomRatioWidth` : 'customRatioWidth';
    const hKey = prefix ? `${prefix}CustomRatioHeight` : 'customRatioHeight';
    return `<div class="inline-fields">
        <span class="inline-label">${escapeHtml(tr('smart.ratio'))}</span>
        <input type="number" data-param="${wKey}" value="${escapeHtml(settings[wKey] || '')}" placeholder="W">
        <span class="inline-divider">:</span>
        <input type="number" data-param="${hKey}" value="${escapeHtml(settings[hKey] || '')}" placeholder="H">
    </div>`;
}
function renderInlineCustomSizeFields(prefix=''){
    const resKey = prefix ? `${prefix}Resolution` : 'resolution';
    if(settings[resKey] !== 'custom') return '';
    const wKey = prefix ? `${prefix}CustomWidth` : 'customWidth';
    const hKey = prefix ? `${prefix}CustomHeight` : 'customHeight';
    return `<div class="inline-fields">
        <span class="inline-label">${escapeHtml(tr('smart.size'))}</span>
        <input type="number" data-param="${wKey}" value="${escapeHtml(settings[wKey] || '')}" placeholder="${escapeHtml(tr('smart.width'))}">
        <span class="inline-divider">×</span>
        <input type="number" data-param="${hKey}" value="${escapeHtml(settings[hKey] || '')}" placeholder="${escapeHtml(tr('smart.height'))}">
    </div>`;
}
function renderQualityControl(){
    if(!imageModelSupportsQuality(settings)) return '';
    const labels = {auto:tr('smart.qualityAuto'), low:tr('smart.qualityLow'), medium:tr('smart.qualityMid'), high:tr('smart.qualityHigh')};
    if(settings.engine === 'api' && isGptImage25Model(settings.model)){
        labels.xhigh = tr('smart.qualityXhigh');
        labels.max = tr('smart.qualityMax');
    }
    const value = Object.prototype.hasOwnProperty.call(labels, settings.quality) ? settings.quality : 'auto';
    if(settings.quality !== value) settings.quality = value;
    return `<div class="smart-control quality-control">
        <button class="smart-pill" type="button"><i data-lucide="sliders-horizontal"></i><span>${escapeHtml(labels[value] || value)}</span></button>
        <div class="smart-popover compact-popover">
            <div class="smart-popover-title">${escapeHtml(tr('smart.quality'))}</div>
            <div class="seg-row">
                ${Object.entries(labels).map(([k, l]) => `<button type="button" class="${k === value ? 'active' : ''}" data-smart-param="quality" data-smart-value="${escapeHtml(k)}">${escapeHtml(l)}</button>`).join('')}
            </div>
        </div>
    </div>`;
}
