function canvasImageDragPayload(node, index=0){
    const img = node?.images?.[index];
    if(!img?.url) return null;
    return {url:img.url, name:img.name || node.title || 'image'};
}
// 迁移旧数据：早期把图片节点作为成员（items[]）放进分组的画布，统一把这些图片吸收进 group.images，
// 让它们显示为卡片内的缩略图网格（新模型）。一次性、幂等。
function migrateSmartGroupImageMembers(){
    let changed = false;
    nodes.filter(isSmartGroupNode).forEach(group => {
        const imageMemberIds = (Array.isArray(group.items) ? group.items : [])
            .map(id => nodes.find(n => n.id === id))
            .filter(m => m && isSmartImageNode(m) && (m.images || []).some(img => img?.url))
            .map(m => m.id);
        imageMemberIds.forEach(id => {
            const member = nodes.find(n => n.id === id);
            if(member && absorbImageNodeIntoSmartGroup(group, member)) changed = true;
        });
    });
    return changed;
}
async function loadCanvasShareSession(){
    if(!sharedCanvasMode) return true;
    try {
        const sessionQuery = shareQueryId && shareQueryToken
            ? `?${new URLSearchParams({share_id:shareQueryId, token:shareQueryToken}).toString()}`
            : '';
        const res = await fetch(`/api/canvas-share/session${sessionQuery}`, {cache:'no-store'});
        const data = await res.json().catch(() => ({}));
        if(!res.ok) throw new Error(data.detail || '分享链接无效或已过期');
        const projectScopedShare = data.scope === 'project' && data.project_id && String(sourceProjectId || '') === String(data.project_id);
        if(data.canvas_id && canvasId && data.canvas_id !== canvasId && !projectScopedShare) throw new Error('此分享链接与当前画布不匹配');
        canvasShareSession = data;
        sharedCanvasReadOnly = String(data.role || 'viewer') !== 'editor';
        document.body.classList.add('canvas-share-mode');
        if(sharedCanvasReadOnly) document.body.classList.add('canvas-share-readonly');
        const banner = document.getElementById('canvasShareBanner');
        if(banner){
            banner.hidden = false;
            banner.classList.remove('is-error');
            const roleText = sharedCanvasReadOnly ? '仅查看' : '可编辑';
            const scopeText = data.scope === 'project' ? '当前项目' : '此画布';
            const assetText = data.allow_assets === false ? '素材受限' : '素材可引用';
            banner.querySelector('[data-share-banner-text]')?.replaceChildren(document.createTextNode(`共享中 · ${roleText} · ${scopeText} · ${assetText} · 服务器在分享者电脑`));
        }
        return true;
    } catch(error){
        const message = (!shareQueryId || !shareQueryToken)
            ? '此页面缺少分享凭证，请从“分享画布”窗口重新复制完整链接'
            : (error.message || '分享链接无效或已过期');
        const banner = document.getElementById('canvasShareBanner');
        if(banner){
            banner.hidden = false;
            banner.classList.add('is-error');
            banner.querySelector('[data-share-banner-text]')?.replaceChildren(document.createTextNode(message));
        }
        toast(message);
        return false;
    }
}

async function loadCanvas(){
    if(!canvasId) return;
    try {
        const res = await fetch(`/api/canvases/${encodeURIComponent(canvasId)}`);
        if(!res.ok) return;
        const data = await res.json();
        canvas = data.canvas;
        rememberCanvasListProject(canvas.project || 'default');
        canvasUsesConnections = Object.prototype.hasOwnProperty.call(canvas || {}, 'connections');
        document.title = canvas.title || tr('canvas.smartCanvas');
        document.getElementById('smartTitle').textContent = canvas.title || tr('canvas.smartCanvas');
        migratedLegacySmartUploadNodes = false;
        migratedInvalidImageTaskRecoveries = false;
        sharedEditorInitialSelectionApplied = false;
        nodes = (Array.isArray(canvas.nodes) ? canvas.nodes : []).map(normalizeLegacySmartNode).filter(Boolean);
        nodes.forEach(node => {
            normalizeSmartCameraNode(node);
            normalizeSmartCompareNode(node);
        });
        migrateSmartGroupImageMembers();
        canvas.connections = Array.isArray(canvas.connections) ? canvas.connections : [];
        const comfyWorkflowIds = new Set(nodes.filter(isSmartComfyWorkflowNode).map(node => node.id));
        const comfyOutputIds = new Set(canvas.connections
            .filter(conn => comfyWorkflowIds.has(conn.from) && conn.kind === 'flow')
            .map(conn => conn.to));
        nodes.forEach(node => {
            if(node.type === 'smart-image' && comfyOutputIds.has(node.id)
                && node.runSettings?.engine === 'comfy' && (node.runAt || node.pending || node.runFinishedAt)){
                node.type = SMART_UPLOAD_NODE_TYPE;
                migratedLegacySmartUploadNodes = true;
            }
        });
        // 以服务器原始节点作为保存基线；后面的恢复/清理变更需要落盘，
        // 否则刷新后虽然能暂时解除卡住状态，服务器仍会保留旧的 running 标记。
        collabCaptureSnapshot(canvas, nodes);
        nodes.forEach(n => {
            if(migrateInvalidImageTaskRecoveries(n)) migratedInvalidImageTaskRecoveries = true;
            const pendingTasks = smartPendingTasks(n);
            if(pendingTasks.length){
                n.pending = pendingTasks.length;
                n.running = false;
            } else if(smartNodeHasDisplayResult(n)){
                markSmartNodeComplete(n, {hideTimer:true});
            } else if(n.pending || n.queued){
                clearSmartNodeBusyState(n);
            }
        });
        const interruptedRunState = !sharedCanvasMode && clearInterruptedSmartNodeStates();
        const cleanedCompletedState = clearCompletedNodeBusyStates();
        const recoveredLoopOutputs = recoverStuckLoopOutputsFromLogs();
        const hiddenCompletedTimers = hideCompletedRunTimers();
        const cleanedDetachedInputs = cleanupDetachedRunInputRefs();
        viewport = {...viewport, ...(canvas.viewport || {})};
        viewport.scale = safeScale(viewport.scale);
        // 共享编辑者首次进入时默认选中当前视口内、距离视口中心最近的一张可操作图片，
        // 让节点工具栏、缩放柄和连接入口立即可见；只读访客仍保持纯预览状态。
        // 必须放在载入画布 viewport 之后，否则旧画布的偏移会把选中目标算到屏幕外。
        ensureSharedEditorInitialSelection();
        if(canvas.settings) settings = {...settings, ...canvas.settings};
        normalizeSmartVideoModeSettings(settings, true);
        nodes.forEach(node => {
            if(node.runSettings) normalizeSmartVideoModeSettings(node.runSettings, true);
        });
        canvasDefaultSmartSettings = cloneSmartSettings(settings);
        loadRecentSmartSettings();
        if(settings.comfy_workflow && !settings.comfyWorkflow) settings.comfyWorkflow = settings.comfy_workflow;
        if(settings.comfy_params && !settings.comfyParams) settings.comfyParams = settings.comfy_params;
        updateProviderModels();
        applyViewport();
        render();
        if(migratedLegacySmartUploadNodes || migratedInvalidImageTaskRecoveries || cleanedDetachedInputs || interruptedRunState || cleanedCompletedState || recoveredLoopOutputs || hiddenCompletedTimers) scheduleSave();
        startCanvasMetaPoll();
    } catch(e) { toast(tr('smart.toastCanvasFail')); }
}
function scheduleSave(){
    clearTimeout(saveTimer);
    saveTimer = setTimeout(saveCanvas, 450);
}
async function saveCanvas(){
    if(!canvasId || !canvas) return;
    if(sharedCanvasReadOnly) return;
    savePromptDraftForCurrent();
    nodes.forEach(node => {
        normalizeSmartCameraNode(node);
        normalizeSmartCompareNode(node);
        node.images = (node.images || []).map(img => mediaItemForStorage(stripImageGenerationMeta(img)));
        if(node.runSettings) node.runSettings = settingsForStorage(node.runSettings);
    });
    canvas.nodes = nodes;
    canvas.settings = settingsForStorage(canvasDefaultSmartSettings || initialSmartSettings);
    canvas.viewport = {...viewport};
    const storageCanvas = canvasForStorage();
    const diff = collabNodeDiff(storageCanvas.nodes || []);
    const changedTitle = String(collabCanvasSnapshot.title || '') !== String(storageCanvas.title || '');
    const changedIcon = String(collabCanvasSnapshot.icon || '') !== String(storageCanvas.icon || '');
    const changedConnections = collabCanvasSnapshot.connections !== collabJsonSignature(storageCanvas.connections || []);
    const changedViewport = collabCanvasSnapshot.viewport !== collabJsonSignature(storageCanvas.viewport || {});
    const changedLogs = collabCanvasSnapshot.logs !== collabJsonSignature(storageCanvas.logs || []);
    const changedSettings = collabCanvasSnapshot.settings !== collabJsonSignature(storageCanvas.settings || {});
    const hasChanges = diff.changes.length || diff.deleted_ids.length || changedTitle || changedIcon || changedConnections || changedViewport || changedLogs || changedSettings;
    const useIncremental = collabSocketIsReady() && collabConnected;
    if(useIncremental && !hasChanges) return;
    canvasSyncInFlight = true;
    const saveController = new AbortController();
    const saveTimeout = setTimeout(() => saveController.abort(), SMART_CANVAS_SAVE_TIMEOUT_MS);
    try {
        const incrementalBody = {
            changes:diff.changes,
            deleted_ids:diff.deleted_ids,
            client_id:smartClientId,
            base_updated_at:Number(canvas.updated_at || 0)
        };
        if(changedConnections) incrementalBody.connections = storageCanvas.connections || [];
        if(changedViewport) incrementalBody.viewport = storageCanvas.viewport || {x:0,y:0,scale:1};
        if(changedTitle) incrementalBody.title = storageCanvas.title || tr('smart.title');
        if(changedIcon) incrementalBody.icon = storageCanvas.icon || 'sparkles';
        if(changedLogs) incrementalBody.logs = storageCanvas.logs || [];
        if(changedSettings) incrementalBody.settings = storageCanvas.settings || {};
        const requestUrl = useIncremental
            ? `/api/canvases/${encodeURIComponent(canvasId)}/nodes`
            : `/api/canvases/${encodeURIComponent(canvasId)}`;
        const requestBody = useIncremental ? incrementalBody : {
            title:storageCanvas.title || tr('smart.title'),
            icon:storageCanvas.icon || 'sparkles',
            nodes:storageCanvas.nodes || [],
            connections:storageCanvas.connections || [],
            viewport:storageCanvas.viewport || {x:0,y:0,scale:1},
            logs:storageCanvas.logs || [],
            settings:storageCanvas.settings,
            base_updated_at:storageCanvas.updated_at || canvas.updated_at || 0,
            client_id:smartClientId
        };
        const res = await fetch(requestUrl, {
            method:useIncremental ? 'PATCH' : 'PUT',
            headers:{'Content-Type':'application/json'},
            signal:saveController.signal,
            body:JSON.stringify(requestBody)
        });
        if(res.ok){
            const data = await res.json();
            if(data.canvas){
                collabApplyReturnedRevisions(data.canvas);
                canvas.updated_at = data.canvas.updated_at || canvas.updated_at;
                collabCaptureSnapshot(canvas, nodes);
            }
        } else if(res.status === 409) {
            // 冲突：别人先保存了。合并对方的状态（节点 id 合并、图片取并集，谁都不丢），
            // 然后用对方最新的 updated_at 作为基底重存，把合并结果落盘——而不是直接覆盖对方。
            const data = await res.json().catch(() => ({}));
            const serverCanvas = data.detail?.canvas;
            if(serverCanvas){
                if(useIncremental){
                    openCollabConflictDialog(serverCanvas, data.detail?.conflicts || [], diff.changes, diff.deleted_ids);
                } else {
                    applyMergedServerCanvas(serverCanvas);
                    nodes.forEach(node => {
                        node.images = (node.images || []).map(img => mediaItemForStorage(stripImageGenerationMeta(img)));
                        if(node.runSettings) node.runSettings = settingsForStorage(node.runSettings);
                    });
                    canvas.nodes = nodes;
                    collabCaptureSnapshot(canvas, nodes);
                }
            } else if(data.detail?.updated_at) {
                canvas.updated_at = data.detail.updated_at;
            }
            if(!useIncremental){
                clearTimeout(saveTimer);
                saveTimer = setTimeout(saveCanvas, 300);
            }
        } else if(res.status === 423){
            const data = await res.json().catch(() => ({}));
            (data.detail?.locks || data.locks || []).forEach(lock => {
                if(lock?.node_id) collabLocks.set(String(lock.node_id), lock);
            });
            render();
            toast(data.detail?.message || '有其他成员正在编辑这些节点');
        }
    } catch(e) {
        if(e?.name === 'AbortError') console.warn('[Smart Canvas] 保存画布超时，已继续当前任务');
    } finally {
        clearTimeout(saveTimeout);
        canvasSyncInFlight = false;
    }
}
