function createNode(x, y, images=[], options={}){
    if(!collabCanMutateCanvas()) return null;
    if(!options.skipUndo) pushUndo();
    const nodeImages = (images || []).map(img => ({...img}));
    const nodeType = options.nodeType || 'smart-image';
    const emptyTitle = options.title
        || (nodeType === SMART_PAINT_NODE_TYPE
            ? tr('smart.createPaintNode')
            : nodeType === SMART_DRAWING_BOARD_NODE_TYPE
            ? tr('smart.createDrawingBoardNode')
            : tr('smart.createImportNode'));
    const node = {id:uid('smart'), type:nodeType, x, y, title:nodeImages.length > 1 ? 'Group' : nodeImages.length ? 'Image' : emptyTitle, images:nodeImages, created_at:Date.now()};
    if(nodeType === SMART_DRAWING_BOARD_NODE_TYPE){
        const size = window.SmartDrawingBoard?.defaultNodeSize?.() || {width:500, height:430};
        node.w = Math.max(340, Math.round(Number(options.w) || size.width));
        node.h = Math.max(320, Math.round(Number(options.h) || size.height));
        node.drawingBoard = window.SmartDrawingBoard?.defaultState?.() || {
            version:1, width:1024, height:768, background:'white', tool:'brush',
            color:'#111827', size:18, opacity:1, dirty:false, strokes:[]
        };
        normalizeSmartDrawingBoardNode(node);
    }
    if(nodeType === SMART_COMFY_WORKFLOW_NODE_TYPE){
        node.w = Math.max(320, Math.round(Number(options.w) || 390));
        node.h = Math.max(190, Math.round(Number(options.h) || 238));
    }
    node.scale = nodeImages.length > 1 ? MEDIA_GROUP_DEFAULT_SCALE : mediaNodeDefaultScale(node);
    inheritNodeMetaFromImage(node);
    if(nodeType === SMART_PAINT_NODE_TYPE && !node.runSettings){
        const recent = recentSmartSettingsForMode();
        const source = ['api','volcengine'].includes(recent.engine)
            ? recent
            : {...cloneSmartSettings(initialSmartSettings), ...recentSmartSettingsForMode('api:image'), engine:'api'};
        node.runSettings = settingsForStorage(apiOnlySettings(source));
    }
    nodes.push(node);
    if(options.select !== false) selectedId = node.id;
    render();
    scheduleSave();
    return node;
}
