        const tx = isHistory ? tr.x + tr.width / 2 : (toPort?.x ?? tr.x);
        const ty = isHistory ? tr.y : (toPort?.y ?? tr.y + tr.height / 2);
        const dx = Math.max(50, Math.abs(tx - fx) * 0.45);
