function taskProgressNumber(value, key=''){
    if(value == null || typeof value === 'object') return null;
    const text = String(value).trim();
    if(!text) return null;
    const match = text.match(/-?\d+(?:\.\d+)?/);
    if(!match) return null;
    let number = Number(match[0]);
    if(!Number.isFinite(number)) return null;
    const normalizedKey = String(key || '').toLowerCase();
    if(!normalizedKey.includes('percent') && !normalizedKey.includes('percentage') && !normalizedKey.includes('ratio') && number > 0 && number <= 1){
        number *= 100;
    }
    return Math.max(0, Math.min(100, number));
}
function taskProgressFromObject(task){
    if(!task || typeof task !== 'object') return null;
    const sources = [task, task.progressData, task.data, task.result, task.task, task.raw, task.raw?.data].filter(item => item && typeof item === 'object');
    const directKeys = [
        'progress_percent', 'progressPercentage', 'percentage', 'percent',
        'progress', 'progress_value', 'progressValue', 'completion', 'completed_percent'
    ];
    for(const source of sources){
        for(const key of directKeys){
            const value = taskProgressNumber(source[key], key);
            if(value != null) return {value, source:'real'};
        }
        const completed = Number(source.completed ?? source.completed_count ?? source.current ?? source.done ?? source.finished);
        const total = Number(source.total ?? source.total_count ?? source.count ?? source.target);
        if(Number.isFinite(completed) && Number.isFinite(total) && total > 0){
            return {value:Math.max(0, Math.min(100, completed * 100 / total)), source:'real'};
        }
        const message = String(source.message || source.status_message || '').trim();
        const messagePercent = message.match(/(\d+(?:\.\d+)?)\s*%/);
        if(messagePercent) return {value:Math.max(0, Math.min(100, Number(messagePercent[1]))), source:'real'};
    }
    return null;
}
function taskQueueInfo(task){
    const info = task?.queueInfo || task?.queue_info || task?.queue || {};
    return info && typeof info === 'object' ? info : {};
}
const smartComfyTaskProgressByNode = new Map();
function generationTaskProgress(node, task=null){
    const real = taskProgressFromObject(task);
    if(real) return {...real, value:Math.round(real.value)};
    if(node?.runSettings?.engine !== 'comfy') return {value:0, source:'indeterminate'};
    const status = String(task?.status || task?.task_status || '').trim().toLowerCase();
    const queued = status === 'queued' || status === 'pending' || status === 'waiting' || Boolean(node?.queued);
    if(queued) return {value:0, source:'estimated'};
    const submitting = status === 'submitting' || status === 'created' || (node?.running && !task);
    let startedAt = Number(task?.startedAt || task?.started_at || task?.createdAt || task?.created_at || node?.runStartedAt || 0);
    // 后端 Unix 时间戳是秒，浏览器 Date.now() 是毫秒；统一后才不会一开始就跳到 92%。
    if(startedAt > 0 && startedAt < 100000000000) startedAt *= 1000;
    const elapsedSeconds = startedAt > 0 ? Math.max(0, (Date.now() - startedAt) / 1000) : 0;
    if(submitting){
        if(node?.runSettings?.engine !== 'comfy') return {value:4, source:'estimated'};
        return {value:Math.min(24, Math.max(4, Math.round(4 + elapsedSeconds * 0.45))), source:'estimated'};
    }
    const estimated = Math.min(92, Math.max(8, Math.round(8 + elapsedSeconds * 1.35)));
    return {value:estimated, source:'estimated'};
}
function generationTaskDisplay(node, task=null, compact=false){
    const status = String(task?.status || '').trim().toLowerCase();
    const progress = generationTaskProgress(node, task);
    const queue = taskQueueInfo(task);
    const queueIndex = Number(queue.queue_idx ?? queue.position ?? queue.index);
    const queueLength = Number(queue.queue_length ?? queue.total ?? queue.length);
    let startedAt = Number(task?.startedAt || task?.started_at || task?.createdAt || task?.created_at || node?.runStartedAt || 0);
    if(startedAt > 0 && startedAt < 100000000000) startedAt *= 1000;
    const value = progress.source === 'indeterminate'
        ? formatRunDuration(startedAt > 0 ? Math.max(0, nowMs() - startedAt) : 0)
        : `${progress.value}%`;
    if(status === 'succeeded') return {phase:'waiting', value:'100%', label:'接收结果', source:'real', percent:100};
    if(status === 'queued' || status === 'pending' || status === 'waiting' || node?.queued){
        const queueLabel = Number.isFinite(queueIndex) && Number.isFinite(queueLength) && queueLength > 0
            ? `排队中 · 第 ${Math.max(1, queueIndex)}/${queueLength} 位`
            : (compact ? '排队中' : '排队中 · 等待空位');
        return {phase:'queued', value, label:queueLabel, source:progress.source, percent:progress.value};
    }
    if(status === 'running' || status === 'processing' || status === 'in_progress'){
        const label = progress.source === 'indeterminate' ? '生成中 · 已等待'
            : progress.source === 'estimated' ? '生成中 · 预计进度'
            : compact ? '生成中' : '生成中 · 实时进度';
        return {phase:'running', value, label, source:progress.source, percent:progress.value};
    }
    if(node?.running && !task){
        return {phase:'submitting', value, label:compact ? '提交中' : '正在提交任务', source:progress.source, percent:progress.value};
    }
    return {phase:'waiting', value, label:compact ? '等待中' : '等待上游结果', source:progress.source, percent:progress.value};
}
