    if(!el) return;
    el.classList.add('drop-target');
    const target = nodes.find(node => node.id === targetId);
    el.classList.toggle('drop-target-group', Boolean(target && isSmartGroupNode(target)));
    el.classList.toggle('drop-target-image', Boolean(target && isSmartImageNode(target)));
