function bindInputThumbsDrag(node, items, manualRefKeys=new Set()){
    if(!inputThumbsRow) return;
    inputThumbsRow.querySelectorAll('.input-thumb').forEach(el => {
        const index = Number(el.dataset.thumbIndex || -1);
        const item = items[index];
        const key = inputRefKey(item);
        const canReorder = items.length > 1 && (manualRefKeys.has(key) || Boolean(item?.nodeId));
        // 统一使用指针拖动，避免浏览器原生拖拽的 ghost image、拖动阈值和
        // dragstart 冒泡与画布节点手势相互干扰。
        el.draggable = false;
        el.dataset.inputReorderable = canReorder ? '1' : '0';
        el.addEventListener('click', e => {
            e.preventDefault();
            e.stopPropagation();
        });
        if(!canReorder) return;
        let pointerDrag = null;
        const targetAtPoint = event => {
            const hit = document.elementFromPoint(event.clientX, event.clientY);
            const target = hit?.closest?.('.input-thumb');
            if(!target || !inputThumbsRow.contains(target)) return null;
            const targetIndex = Number(target.dataset.thumbIndex || -1);
            if(!Number.isInteger(targetIndex) || targetIndex < 0 || targetIndex === index) return null;
            // 落到另一张缩略图上即跨过它。两张图只需拖到对方身上就能交换顺序，
            // 无需精确放到目标的左半边或右半边。
            return {target, targetIndex, placement:targetIndex > index ? 'after' : 'before'};
        };
        const updatePointerDropMarker = event => {
            const target = targetAtPoint(event);
            clearInputThumbDropMarkers();
            if(pointerDrag?.dragging) el.classList.add('dragging');
            if(!target) return null;
            target.target.dataset.dropPlacement = target.placement;
            target.target.classList.add(target.placement === 'before' ? 'drop-before' : 'drop-after');
            return target;
        };
        const finishPointerDrag = (event, commit=true) => {
            if(!pointerDrag || event.pointerId !== pointerDrag.pointerId) return;
            const state = pointerDrag;
            const target = state.dragging && commit ? updatePointerDropMarker(event) : null;
            pointerDrag = null;
            try { el.releasePointerCapture?.(event.pointerId); } catch(_) {}
            clearInputThumbDropMarkers();
            document.body.classList.remove('smart-input-thumb-drag');
            el.setAttribute('aria-grabbed', 'false');
            if(!state.dragging || !target) return;
            event.preventDefault();
            event.stopPropagation();
            reorderInputThumb(node, items, index, target.targetIndex, target.placement);
        };
        el.addEventListener('pointerdown', event => {
            if(event.pointerType === 'mouse' && event.button !== 0) return;
            if(event.target.closest?.('.input-thumb-remove')) return;
            event.preventDefault();
            event.stopPropagation();
            pointerDrag = {
                pointerId:event.pointerId,
                startX:event.clientX,
                startY:event.clientY,
                dragging:false
            };
            el.setPointerCapture?.(event.pointerId);
        }, true);
        el.addEventListener('pointermove', event => {
            if(!pointerDrag || event.pointerId !== pointerDrag.pointerId) return;
            const moved = Math.hypot(event.clientX - pointerDrag.startX, event.clientY - pointerDrag.startY) > 6;
            if(!pointerDrag.dragging && !moved) return;
            pointerDrag.dragging = true;
            event.preventDefault();
            event.stopPropagation();
            document.body.classList.add('smart-input-thumb-drag');
            el.setAttribute('aria-grabbed', 'true');
            updatePointerDropMarker(event);
        }, true);
        el.addEventListener('pointerup', event => finishPointerDrag(event, true), true);
        el.addEventListener('pointercancel', event => finishPointerDrag(event, false), true);
    });
}
function clearInputThumbDropMarkers(){
    inputThumbsRow?.querySelectorAll('.input-thumb.drop-before,.input-thumb.drop-after,.input-thumb.dragging')
        .forEach(el => {
            delete el.dataset.dropPlacement;
            el.classList.remove('drop-before', 'drop-after', 'dragging');
        });
}
