    if(!items.length) return;
    const summary = items.slice(0, 2).map(file => {
        const meta = file.auto_compressed || {};
        const name = meta.original_name || file.name || '图片';
        const before = smartUploadSizeLabel(meta.original_bytes);
        const after = smartUploadSizeLabel(meta.uploaded_bytes);
        const dimensions = meta.width && meta.height ? `，${meta.width}×${meta.height}` : '';
        return `${name}${before && after ? ` ${before} → ${after}` : ''}${dimensions}`;
    }).join('；');
