    if(!scope.valid || !prompt) return {ok:false,reason:scope.reason || '没有可写入的生成提示词。'};
    pushUndo();
    ensureCanvasTaskScopeFormalConnections(scope);
    let target = scope.targetNodeId ? nodes.find(node => node.id === scope.targetNodeId) : null;
    let created = false;
    let connected = 0;
    if(!canvasTaskScopeIsReusableTarget(target)){
        target = createPaintNodeAt(canvasTaskScopePlacement(scope),{
            select:false,
            skipUndo:true,
            title:String(action?.title || 'Agent 生成').trim().slice(0,80) || 'Agent 生成'
        });
        created = Boolean(target);
        (scope.sourceNodeIds || []).forEach(sourceId => {
            if(target && connectInputNode(sourceId,target.id)) connected += 1;
        });
    }
