    const cameraRefs = uniqueReferenceImages(smartCameraInputImages(camera, false, ctx).filter(img => img?.url));
    const imageRefs = imageRefsOnly(Array.isArray(refs) ? refs : []).filter(img => img?.url);
    const uniqueRefs = [];
    const seen = new Set();
    [...cameraRefs, ...imageRefs].forEach(ref => {
        const key = ref?.url || ref?.comfy_name || ref?.name || '';
        if(!key || seen.has(key)) return;
        seen.add(key);
        uniqueRefs.push(ref);
    });
    if(cameraRefs.length > 1){
        throw new Error('视角控制节点当前只支持一张参考图');
    }
