    if(!connectionEraseState && connectionEraseModifierActive(e) && (Number(e.buttons) & 6) && !connectionEraseTargetExcluded(e.target)){
        const button = Number(e.buttons) & 2 ? 2 : 1;
        if(beginConnectionErase(e, button)) return;
    }
